insert into CHB_MKT_HOLIDAY(
BUSI_DATE,
MARKET_CODE,
IS_HOLIDAY,
DEPT_CODE,
STATUS,CREATE_TIME,
CREATE_USER
) select
BUSI_DATE,
MARKET_CODE,
IS_HOLIDAY,
DEPT_CODE,
STATUS,CREATE_TIME,
CREATE_USER
from ( select TEMP.* from (
SELECT #{item,jdbcType=DATE} AS BUSI_DATE, #{marketCalendarType} AS MARKET_CODE FROM DUAL
) TEMP where not exists (select 1 from CHB_MKT_HOLIDAY CII where TEMP.BUSI_DATE = CII.BUSI_DATE AND TEMP.MARKET_CODE = CII.MARKET_CODE) ) de ;
UPDATE CHB_MKT_HOLIDAY as A, ( select IS_HOLIDAY from ( select TEMP.* from (
SELECT #{item,jdbcType=DATE} AS BUSI_DATE, #{marketCalendarType} AS MARKET_CODE FROM DUAL
) TEMP ) de ) AS B set A.* = B.* where exists (select 1 from CHB_MKT_HOLIDAY CII where TEMP.BUSI_DATE = CII.BUSI_DATE AND TEMP.MARKET_CODE = CII.MARKET_CODE);
